import{_ as s,c as t,o as a,ag as o}from"./chunks/framework.bCALENAD.js";const p=JSON.parse('{"title":"Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"en/faq.md","lastUpdated":1720813884000}'),i={name:"faq.md"};function r(n,e,l,d,u,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="questions-answers" tabindex="-1">Questions &amp; Answers <a class="header-anchor" href="#questions-answers" aria-label="Permalink to &quot;Questions &amp; Answers&quot;">​</a></h1><p>Here we answer the questions you might have.</p><details class="details custom-block"><summary>How do I install MySpeed?</summary><p>Depending on your operating system these instructions are different. Here you can find the instructions for <a href="./setup/windows">Windows</a> and <a href="./setup/linux">Linux</a>.<br> However, it is strongly recommended to install MySpeed on Linux.</p></details><details class="details custom-block"><summary>What are the requirements?</summary><p>It depends on what kind of bandwidth you have. For Linux, for example, it would be like this: If you have a maximum of 100 Mbps on, then a RaspberryPi 1 or any other old computer will do the trick. If you have a Gbit line, a Raspberry Pi 4 or a PC with 1Gbit LAN support would be important.</p></details><details class="details custom-block"><summary>Can I use MySpeed despite VPN?</summary><p>As long as you don&#39;t use your VPN service on the same system as the one where MySpeed is running, it&#39;s not a problem. Otherwise, your VPN might distort the results or not reflect them realistically.</p></details><details class="details custom-block"><summary>Does this information serve as official proof for my ISP?</summary><p>No. The speed tests have to be done by the speed test service of your provider. In this case MySpeed serves only for information purposes and has no legal guarantees.</p></details><details class="details custom-block"><summary>What can influence the speed tests?</summary><p>There are many factors that can influence the speed tests. For example, if you have a lot of background services running, they can affect the results. It is best to turn them off at the respective test times, otherwise your results could be manipulated.</p></details><details class="details custom-block"><summary>What happens to the old test results?</summary><p>The old test results are automatically deleted as soon as they are older than 30 days.</p></details><details class="details custom-block"><summary>Does it have to run permanently?</summary><p>We recommend it to get better results. If it bothers you while streaming movies etc., you can also pause it via the web interface for a certain time or manually. For 24/7 operation, we recommend a system that doesn&#39;t need a lot of watts. In this case we recommend a Raspberry Pi. If you already have a server running all the time, you can also run it there in parallel.</p></details><details class="details custom-block"><summary>How can I distinguish between manual and automatic speed tests?</summary><p>Click on the clock symbol of the respective test. There you will find all information about the speed test.</p></details><details class="details custom-block"><summary>Does the &quot;Recommendations&quot; function show my correct bandwidth?</summary><p>No, this is a calculated value from your last 10 speed tests. The available bandwidth will be found in your connection contract.</p></details><details class="details custom-block"><summary>Can the developer see my test results?</summary><p>No, the test results are only visible locally on the server.</p></details><details class="details custom-block"><summary>Why should I configure frequencies?</summary><p>It depends very much on your internet. For example, if you have a very bad internet, you should rather decrease the frequency. If your internet is quite fast, you can increase it. On this basis, more or less tests will be made, depending on the situation.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>It is very likely that background services are affecting your speeds. It is best to turn them off at the respective test times, otherwise your results could be manipulated.</p></div></details><details class="details custom-block"><summary>How do I reset my password?</summary><p>You forgot your MySpeed password? It happens, no problem. To reset it, navigate to the installation location (<code>cd /opt/myspeed</code>) and execute the following command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;const {Sequelize} = require(&#39;sequelize&#39;);const db = new Sequelize({dialect: &#39;sqlite&#39;, storage: &#39;data/storage.db&#39;});db.query(&#39;UPDATE config SET value=? WHERE key=?&#39;, {replacements: [&#39;none&#39;, &#39;password&#39;]})&quot;</span></span></code></pre></div><p>Then you can go to the page again and set your password manually 😃</p></details>',14)])])}const h=s(i,[["render",r]]);export{p as __pageData,h as default};
